+type McpCallToolHandler = (
+  request: {
+    method: "tools/call";
+    params: {
+      name: string;
+      arguments?: Record<string, unknown>;
+      _meta?: Record<string, unknown>;
+    };
+  },
+  extra: {
+    requestId: string | number;
+    sessionId?: string;
+    signal: AbortSignal;
+    sendNotification: (notification: unknown) => Promise<void>;
+    sendRequest: (
+      request: unknown,
+      resultSchema: unknown,
+      options?: unknown,
+    ) => Promise<unknown>;
+  },
+) => Promise<unknown>;
+
+interface McpCallToolRequestEnvelope {
+  id: string | number;
+  method: "tools/call";
+  params: {
+    name: string;
+    arguments?: Record<string, unknown>;
+    _meta?: Record<string, unknown>;
+  };
+}
+
+function getCallToolRequestHandler(server: unknown): McpCallToolHandler {
+  const handler = (
+    server as {
+      server: {
+        _requestHandlers: Map<string, McpCallToolHandler>;
+      };
+    }
+  ).server._requestHandlers.get("tools/call");
+
+  if (!handler) {
+    throw new Error("Missing tools/call request handler");
+  }
+
+  return handler;
+}
+
+async function callToolThroughProtocol(
+  server: unknown,
+  request: McpCallToolRequestEnvelope,
+  extra: {
+    sessionId?: string;
+  } = {},
+): Promise<unknown> {
+  const protocol = (
+    server as {
+      server: {
+        _onrequest: (
+          request: McpCallToolRequestEnvelope,
+          extra?: {
+            authInfo?: unknown;
+            requestInfo?: unknown;
+            closeSSEStream?: () => void;
+            closeStandaloneSSEStream?: () => void;
+          },
+        ) => void;
+        _transport?: {
+          sessionId?: string;
+          send: (message: unknown) => Promise<void>;
+        };
+      };
+    }
+  ).server;
+
+  return await new Promise((resolve, reject) => {
+    protocol._transport = {
+      send: async (message) => {
+        const response = message as
+          | { id: string | number; result: unknown }
+          | {
+              id: string | number;
+              error: { code: number; message: string; data?: unknown };
+            };
+
+        if ("error" in response) {
+          reject(
+            new Error(
+              `MCP request ${String(response.id)} failed: ${response.error.message}`,
+            ),
+          );
+          return;
+        }
+
+        resolve(response.result);
+      },
+      ...(extra.sessionId ? { sessionId: extra.sessionId } : {}),
+    };
+
+    protocol._onrequest(request);
+  });
+}
